 "content": "def transform(grid):
    """Mark compartments containing exactly two non-background marks."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, separators):
        result = []
        start = 0
        for p in separators:
            if p >= start:
                if start < p:
                    result.append((start, p))
                start = p + 1
        if start < size:
            result.append((start, size))
        return result

    row_ranges = segments(h, sep_rows)
    col_ranges = segments(w, sep_cols)
    cells = [grid[r][c] for r0, r1 in row_ranges for r in range(r0, r1)
             for c0, c1 in col_ranges for c in range(c0, c1)]
    counts = {v: cells.count(v) for v in set(cells)}
    background = max(counts, key=counts.get)
    output = []
    for r0, r1 in row_ranges:
        row = []
        for c0, c1 in col_ranges:
            marks = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if marks == 2 else 0)
        output.append(row)
    return output

